import{_ as a,o as s,c as i,a6 as t}from"./chunks/framework.BV_S2lHy.js";const k=JSON.parse('{"title":"Simulation workflows","description":"","frontmatter":{},"headers":[],"relativePath":"simulation/workflows.md","filePath":"simulation/workflows.md","lastUpdated":1791578382000}'),n={name:"simulation/workflows.md"};function o(r,e,l,d,h,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="simulation-workflows" tabindex="-1">Simulation workflows <a class="header-anchor" href="#simulation-workflows" aria-label="Permalink to &quot;Simulation workflows&quot;">​</a></h1><p>These workflows use <a href="/hivedocs/simulation/isaac-lab">the Newton-based Isaac Lab installation</a>, checked at simulation commit <a href="https://github.com/hiveboard-bench/isaaclab-hiveboard/commit/1d7a0421154af19883eadc0e5d3b12eda2cb2a00" target="_blank" rel="noreferrer"><code>1d7a042</code></a>. Complete the dependency installation and USD generation first. Run commands from the simulation repository root.</p><h2 id="edit-a-task-s-command-sequence" tabindex="-1">Edit a task&#39;s command sequence <a class="header-anchor" href="#edit-a-task-s-command-sequence" aria-label="Permalink to &quot;Edit a task&#39;s command sequence&quot;">​</a></h2><p>The Viser editor lets you adjust target poses, rotation axes, screw travel, gripper commands, and the tool center point (TCP).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/command_edit.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Isaac-HiveBoard-Franka-BallValve-Play-v0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9080</span></span></code></pre></div><p>Open <code>http://localhost:9080</code> in a browser on the same computer.</p><ol><li>Select a command and adjust its position, orientation, or reference frame.</li><li>Set motion speeds, tolerances, gripper state, and hold time as needed.</li><li>Check the TCP offset relative to the end-effector body.</li><li>Preview the sequence and inspect the inverse-kinematics residuals.</li><li>Click <strong>Save setup</strong>.</li><li>Run the saved sequence with physics before collecting data.</li></ol><p>The editor preview is kinematic. Contact forces, object motion, collisions, and cuRobo plans must be checked in the simulation run.</p><h3 id="saved-setups" tabindex="-1">Saved setups <a class="header-anchor" href="#saved-setups" aria-label="Permalink to &quot;Saved setups&quot;">​</a></h3><p>By default, the editor and player look for <code>configs/&lt;task&gt;.json</code>. A <code>-Play-v0</code> task falls back to its base task&#39;s file when it has no file of its own. An explicit <code>--setup FILE</code> selects a different file.</p><p>The editor saves to the loaded file, or to <code>configs/&lt;task&gt;.json</code> for a new setup. Use <code>--out FILE</code> to choose another output path. Retain the saved JSON with the experiment.</p><p>For example, save a Spot setup to a known path:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/command_edit.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Isaac-HiveBoard-Spot-BallValve-Play-v0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/spot-ball-valve-review.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9080</span></span></code></pre></div><p>After clicking <strong>Save setup</strong>, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/play.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Isaac-HiveBoard-Spot-BallValve-Play-v0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --setup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/spot-ball-valve-review.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  physics=newton_mjwarp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --visualizer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> newton</span></span></code></pre></div><p>Use <code>--no-setup</code> with <code>play.py</code> to inspect the command sequence defined in the task code.</p><h2 id="record-several-environments" tabindex="-1">Record several environments <a class="header-anchor" href="#record-several-environments" aria-label="Permalink to &quot;Record several environments&quot;">​</a></h2><p>The batch recorder runs each selected environment in a separate process and writes MP4 files, logs, and a <code>summary.json</code> under <code>videos/environments/&lt;timestamp&gt;/</code>.</p><p>Preview the default selection:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/record_all_envs.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span></code></pre></div><p>The default selection contains <code>-Play</code> environments, including the light-bulb tasks for all three robots. Add <code>--all</code> to include other variants. To record only the ANYmal light-bulb task:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/record_all_envs.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Isaac-HiveBoard-Anymal-Lamp-Play-v0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --renderer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> newton</span></span></code></pre></div><p>Filter by robot and inspect the commands before recording:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/record_all_envs.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --match</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Franka</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/record_all_envs.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --match</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Franka</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --renderer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> newton</span></span></code></pre></div><p>The batch recorder defaults to RTX rendering. Select <code>--renderer newton</code> for rasterized output. Both <code>ffmpeg</code> and <code>ffprobe</code> must be on <code>PATH</code>. Frame rates are derived separately for each task to preserve simulated timing.</p><p>Inspect the recordings and task outcomes before treating them as successful demonstrations. For light bulb, check the <a href="/hivedocs/simulation/isaac-lab#light-bulb-success-condition">configured screw travel and success condition</a>.</p><h2 id="record-episodes-for-learning" tabindex="-1">Record episodes for learning <a class="header-anchor" href="#record-episodes-for-learning" aria-label="Permalink to &quot;Record episodes for learning&quot;">​</a></h2><h3 id="player-recordings" tabindex="-1">Player recordings <a class="header-anchor" href="#player-recordings" aria-label="Permalink to &quot;Player recordings&quot;">​</a></h3><p>When a task has a recorder configured, <code>play.py</code> writes HDF5 episodes and prints the output path. The standard recorder defaults to <code>logs/recorded_datasets/</code>. The player exports successful and unsuccessful episodes. Use <code>--no-dataset</code> when only visualization or video is needed.</p><p>Inspect outcome labels before selecting episodes for learning. Check the HDF5 schema against the intended training code.</p><h2 id="policy-training" tabindex="-1">Policy training <a class="header-anchor" href="#policy-training" aria-label="Permalink to &quot;Policy training&quot;">​</a></h2><p>Reinforcement and imitation learning now live in <a href="https://github.com/hiveboard-bench/hiveboard-rl" target="_blank" rel="noreferrer"><code>hiveboard-bench/hiveboard-rl</code></a>, checked at commit <a href="https://github.com/hiveboard-bench/hiveboard-rl/commit/34a11c865923aedc3727eb019a8912401c241625" target="_blank" rel="noreferrer"><code>34a11c8</code></a>. The core <code>isaaclab-hiveboard</code> repository provides environments, scripted controllers, command editing, and recording. Its former <code>scripts/rl/</code>, <code>scripts/imitation/</code>, and <code>imitation</code> dependency extra have been removed.</p><p>The learning repository installs its own pinned <code>isaaclab-hiveboard</code> submodule. With <code>just</code> and <code>uv</code> installed, start in a separate checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/hiveboard-bench/hiveboard-rl.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiveboard-rl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>Generate USD assets inside <code>dependencies/isaaclab-hiveboard</code> using that checkout&#39;s generation recipes, or use <code>just sync-assets /path/to/isaaclab-hiveboard</code> to copy generated assets from a checkout matching the pinned core version. Then run <code>just list-envs</code> to inspect the combined core and learning registry. Keep the learning repository commit and its core submodule commit with experiment records.</p><h3 id="reinforcement-learning" tabindex="-1">Reinforcement learning <a class="header-anchor" href="#reinforcement-learning" aria-label="Permalink to &quot;Reinforcement learning&quot;">​</a></h3><p>The learning package registers ANYmal <code>-RL-v0</code> and <code>-RL-Play-v0</code> tasks for <code>BallValve</code>, <code>SmallValve</code>, <code>M30Thread</code>, and <code>CircuitBreaker</code>.</p><p>The maintainers identify <strong>cuRobo trajectory bank → PPO student → evaluation</strong> as the current working workflow. The bank supplies reset states, tracking rewards, and deviation terminations. The actor uses deployable observations; the critic also receives privileged simulator state.</p><p>Follow the <a href="https://github.com/hiveboard-bench/hiveboard-rl/blob/34a11c865923aedc3727eb019a8912401c241625/README.md#usage" target="_blank" rel="noreferrer">learning README</a> and <a href="https://github.com/hiveboard-bench/hiveboard-rl/blob/34a11c865923aedc3727eb019a8912401c241625/justfile" target="_blank" rel="noreferrer">justfile</a> for <code>rl-bank</code>, <code>rl-student-ppo</code>, <code>rl-eval</code>, and <code>rl-play</code>. Select the same <code>RL_TOOL</code> for bank generation, training, and evaluation. Set parallel environment counts to fit the available GPU memory.</p><p>Inspect each task&#39;s success condition and reset distribution before training. Report the configured goal and validate the complete <a href="/hivedocs/benchmark/tasks">benchmark motion</a> before submitting an evaluation.</p><h3 id="imitation-learning" tabindex="-1">Imitation learning <a class="header-anchor" href="#imitation-learning" aria-label="Permalink to &quot;Imitation learning&quot;">​</a></h3><p>Behavior cloning, DAgger, teacher training, and student distillation remain alternative workflows in the learning repository. Its <code>il-collect</code>, <code>il-train</code>, <code>il-dagger</code>, and <code>il-eval</code> recipes use the imitation-learning scripts and their dataset layout. Follow the <a href="https://github.com/hiveboard-bench/hiveboard-rl/blob/34a11c865923aedc3727eb019a8912401c241625/README.md#usage" target="_blank" rel="noreferrer">learning repository instructions</a> for these workflows; a core player recording is not automatically a compatible training dataset.</p><h2 id="simulation-datasets-and-datahive" tabindex="-1">Simulation datasets and DataHive <a class="header-anchor" href="#simulation-datasets-and-datahive" aria-label="Permalink to &quot;Simulation datasets and DataHive&quot;">​</a></h2><p>Use <a href="/hivedocs/guides/datahive">DataHive</a> for its recording integrations, episode annotations, validation, and dataset submission workflow. The simulation player exports its own HDF5 datasets. Using the same benchmark does not establish file-format compatibility. Check observation names, action units, coordinate frames, timestamps, and metadata before converting data between pipelines.</p><p>A <a href="/hivedocs/contribute/evaluations">learning-dataset contribution</a> has no fixed episode count. Include the simulator commit, task configuration, controller or policy, reset distribution, and outcome labels with simulated data. Keep this separate from a scored benchmark submission, which requires <strong>13 conditions with five trials each</strong>.</p>`,45)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
